window.KAHANOV_FLASHCARD_CHAPTERS = [{"number":1,"title":"Chapter 1","cards":[{"id":"ch01-001","term":"Athletic trainers","definition":"Health care professionals who work with active people. Their services include injury and illness prevention, wellness promotion and education, emergent care, examination, clinical diagnosis, therapeutic intervention, and rehabilitation of injuries and medical conditions."},{"id":"ch01-002","term":"Board of Certification (BOC)","definition":"A credentialing agency that provides certification for athletic trainers and maintains standards for athletic training professional practice and continuing education."},{"id":"ch01-003","term":"Commission on Accreditation of Athletic Training Education (CAATE)","definition":"Organization that develops, maintains, and oversees academic requirements of programs for athletic trainers, which leads to the process of accrediting academic programs."},{"id":"ch01-004","term":"Competencies","definition":"Observable and measurable knowledge and skills applied to a profession."},{"id":"ch01-005","term":"Continuing education","definition":"Education beyond certification that promotes continued competence, development of current knowledge and skills, and enhancement of professional skills and judgment."},{"id":"ch01-006","term":"Health care team","definition":"A group of health care professionals who work together to provide patient-centered care."},{"id":"ch01-007","term":"Interprofessional practice (IPP)","definition":"When two or more professions learn with, about, and from each other to promote effective collaboration and improve health outcomes."},{"id":"ch01-008","term":"National Athletic Trainers’ Association (NATA)","definition":"Membership organization of athletic trainers."},{"id":"ch01-009","term":"Person- or Patient-centered care","definition":"Collaboration of a cohesive team of health care providers to focus on a patient’s needs."},{"id":"ch01-010","term":"Postprofessional education","definition":"Formal education in athletic training beyond the professional master’s degree; it can occur through doctoral education or a residency program."},{"id":"ch01-011","term":"Professional education","definition":"Formal education for entry into the athletic training profession that occurs at the graduate level."},{"id":"ch01-012","term":"Professional ethics","definition":"A standard to ensure that the highest standards of integrity, conduct, and care are maintained and employed."}]},{"number":2,"title":"Chapter 2","cards":[{"id":"ch02-001","term":"Case-control study","definition":"Study that identifies patients who have the outcome of interest (cases) and control patients without the same outcome and looks for exposure of interest."},{"id":"ch02-002","term":"Causal-comparative/quasi-experimental","definition":"A study that determines a cause-and-effect relationship; similar to experimental design but without randomization of groups."},{"id":"ch02-003","term":"Cohort study","definition":"Identifies two groups (cohorts) of patients (one that received the exposure of interest and one that did not) and follows these cohorts for the outcome of interest."},{"id":"ch02-004","term":"Correlational research","definition":"A study that assesses relationships between two or more variables."},{"id":"ch02-005","term":"Critical appraisal","definition":"Authors evaluate and synopsize individual research studies."},{"id":"ch02-006","term":"Descriptive research","definition":"A systematic collection of information through description to describe a phenomenon."},{"id":"ch02-007","term":"Disablement model","definition":"A structure for assessing patient health status that describes the effect of injury or disease on patient function."},{"id":"ch02-008","term":"Evidence-based practice","definition":"The use of the best available evidence from research to guide decision-making in patient treatment and care."},{"id":"ch02-009","term":"Experimental research","definition":"Also known as a true experiment, this study determines cause-and-effect relationships through random assignment to control and experimental groups."},{"id":"ch02-010","term":"Etiology","definition":"In medicine, the cause; set of causes; or attributes that contribute to disease, illness, or injury."},{"id":"ch02-011","term":"Likelihood ratio","definition":"Indicates how many times a patient with an injury or disease will have a certain diagnostic result compared to patients without the injury or disease."},{"id":"ch02-012","term":"Meta-analysis","definition":"A systematic review that uses quantitative methods to summarize the results."},{"id":"ch02-013","term":"Negative predictive value (NPV)","definition":"The proportion of patients with a negative diagnostic test who do not have an injury or disease."},{"id":"ch02-014","term":"Positive predictive value (PPV)","definition":"The proportion of patients with a positive diagnostic test who have an injury or disease."},{"id":"ch02-015","term":"Primary data","definition":"Raw data collected by the researcher."},{"id":"ch02-016","term":"Qualitative","definition":"A non-numerical assessment focusing on opinions, motivations, phenomena, culture, and environment."},{"id":"ch02-017","term":"Quantitative","definition":"A numerical assessment of problems or issues through data."},{"id":"ch02-018","term":"Randomized controlled trials","definition":"Includes a randomized group of patients in an experimental group and a control group."},{"id":"ch02-019","term":"Secondary data","definition":"Data already collected by primary sources that are accessible to researchers, such as the government census or organizational records."},{"id":"ch02-020","term":"Sensitivity","definition":"The proportion of patients with the injury or disease who have a positive test or result. The higher the sensitivity, the more correctly the test identifies patients with that injury or disease."},{"id":"ch02-021","term":"Specificity","definition":"The proportion of patients without the injury or disease who have a negative result. The higher the specificity, the more correctly the test identifies patients without the injury or disease."},{"id":"ch02-022","term":"Systematic review","definition":"Authors have systematically searched for, appraised, and summarized all of the medical literature for a specific topic."}]},{"number":3,"title":"Chapter 3","cards":[{"id":"ch03-001","term":"Effectiveness","definition":"When a prevention program works under real-world conditions."},{"id":"ch03-002","term":"Efficacious","definition":"When a prevention program works under ideal conditions."},{"id":"ch03-003","term":"Epidemiology","definition":"The study of the distribution and determinants of health-related states or events (including disease), and the application of this study to the control of diseases and other health problems."},{"id":"ch03-004","term":"Etiology","definition":"The cause of an injury or illness."},{"id":"ch03-005","term":"Exposure","definition":"The time at risk for developing a condition."},{"id":"ch03-006","term":"Facilitator","definition":"A healthcare professional who assists patients in the treatment or rehabilitation process."},{"id":"ch03-007","term":"Health","definition":"A state of complete physical, mental, and social well-being; not merely the absence of disease or infirmity."},{"id":"ch03-008","term":"Health disparities","definition":"Health differences that are linked with social, economic, or environmental disadvantage."},{"id":"ch03-009","term":"Health equity","definition":"All people have the same opportunity to attain health."},{"id":"ch03-010","term":"Incidence","definition":"The proportion of members of a population who develop new cases of a condition during a specified period of time."},{"id":"ch03-011","term":"Prevalence","definition":"The proportion of members of a population affected by a condition at any given time."},{"id":"ch03-012","term":"Public health","definition":"The science of promoting the health of people and their communities."},{"id":"ch03-013","term":"Risk","definition":"The probability that an adverse event or consequence will occur."},{"id":"ch03-014","term":"Risk factor","definition":"Elements that increase the probability that an adverse event or consequence will occur."},{"id":"ch03-015","term":"Surveillance","definition":"The systematic, ongoing collection, analysis, and dissemination of data in order to prevent and control injuries and illnesses."}]},{"number":4,"title":"Chapter 4","cards":[{"id":"ch04-001","term":"Emotive","definition":"Being demonstrative; expressing emotions."},{"id":"ch04-002","term":"Empathy","definition":"The ability to understand a patient’s perspective."},{"id":"ch04-003","term":"Ethnicity","definition":"A group of people with a distinct shared ancestry and cultural identity."},{"id":"ch04-004","term":"Health disparity","definition":"Differences in health based on social injustices that increase the vulnerability of marginalized groups."},{"id":"ch04-005","term":"Implicit bias","definition":"Unconscious judgment and behavior toward members of a group."},{"id":"ch04-006","term":"Intersectionality","definition":"Overlapping of racial, ethnic, or cultural identities."},{"id":"ch04-007","term":"Marginalization","definition":"Making assumptions and prejudging cultural or ethnic groups."},{"id":"ch04-008","term":"Microassaults","definition":"Most closely aligned with old-fashioned isms like sexism or racism. Assaults can be verbal, nonverbal, implicit, or explicit (i.e., intentional) discriminatory behavior."},{"id":"ch04-009","term":"Microinsult","definition":"Insensitive or rude remarks that convey contempt for the target."},{"id":"ch04-010","term":"Microinvalidations","definition":"Dismissive of the feelings or experiences of a member of a group or denying one’s own biases toward a social group; these behaviors can be unconscious."},{"id":"ch04-011","term":"Oppression","definition":"Unjust treatment with regard to status."},{"id":"ch04-012","term":"Person- or patient-centered care (PCC)","definition":"An approach to therapeutic interactions with patients that is responsive and respectful, placing the patient at the center of the desired outcomes."},{"id":"ch04-013","term":"Power distance","definition":"The level of comfort that group members have with power, influence, and wealth inequalities."},{"id":"ch04-014","term":"Race","definition":"A societal category that is not grounded in biology."},{"id":"ch04-015","term":"Stereotype","definition":"A belief regarding characteristics of a social group; these are preconceived generalizations."},{"id":"ch04-016","term":"Stoicism","definition":"Not showing emotion after painful or pleasurable experiences."}]},{"number":5,"title":"Chapter 5","cards":[{"id":"ch05-001","term":"Big data","definition":"A large set of information that can be analyzed to identify patterns, trends, or human behaviors."},{"id":"ch05-002","term":"Continuous quality improvement (CQI)","definition":"A concept where the health care team members work together to routinely and continually assess how the entity (e.g., department, institution, and clinic) is doing and what can be done better."},{"id":"ch05-003","term":"Health care administration","definition":"The planning, direction, and coordination of medical and health services."},{"id":"ch05-004","term":"ICD-10","definition":"A medical classification system created by the World Health Organization. ICD-10 stands for International Statistical Classification of Diseases and Related Health Problems, 10th edition."},{"id":"ch05-005","term":"ICD-11","definition":"A medical classification system created by the World Health Organization. ICD-11 stands for International Statistical Classification of Diseases and Related Health Problems, 11th edition, and is the global standard for classifying diseases, health conditions, and related health information."},{"id":"ch05-006","term":"Insurance (medical)","definition":"An arrangement with an agency (government or company) to provide guaranteed compensation to providers for medical services in return for payment."},{"id":"ch05-007","term":"Key indicators","definition":"A measurable factor that identifies the success of an organization, employee, or project based on specific desired outcomes."},{"id":"ch05-008","term":"Quantitative","definition":"The use of numbers as measurable data that can be statistically analyzed. Examples include percentages, frequencies, and specific medical values such as laboratory results."},{"id":"ch05-009","term":"Qualitative","definition":"The use of descriptive characteristics that are observable but not numerically measurable; provides input about relationship systems. Examples include focus groups or independent observations."},{"id":"ch05-010","term":"Quality assurance","definition":"Also known as quality improvement; a systematic continuous evaluation of health care services to ensure patient safety and beneficial health care outcomes."}]},{"number":6,"title":"Chapter 6","cards":[{"id":"ch06-001","term":"Advocacy","definition":"The act of supporting a cause, person, or plan."},{"id":"ch06-002","term":"Budgeting","definition":"Creating a planned process to manage the financial resources of the health care setting."},{"id":"ch06-003","term":"Capital equipment","definition":"Fixed assets such as equipment or facilities."},{"id":"ch06-004","term":"Emotional intelligence","definition":"A person’s ability to manage interpersonal relationships with empathy through awareness, control, and emotional expression."},{"id":"ch06-005","term":"Expense","definition":"The amount paid for an item or service."},{"id":"ch06-006","term":"Expendable","definition":"Disposable services or items that are replaced routinely."},{"id":"ch06-007","term":"Facility planning","definition":"The process of managing, designing, and facilitating the function and use of a space."},{"id":"ch06-008","term":"Leadership","definition":"Influence over others or the art of motivating others to achieve a common goal.2"},{"id":"ch06-009","term":"Management","definition":"A process of directing, supervising, or overseeing people."},{"id":"ch06-010","term":"Mission","definition":"A statement of an organization’s definition and philosophy."},{"id":"ch06-011","term":"Operational plan","definition":"Detailed account and plans for individual departments and organizational teams to achieve an organization’s strategic plan goals."},{"id":"ch06-012","term":"Patient advocacy","definition":"When health care providers assist patients with communication regarding their health needs and obtain information pertinent to their health so that they can make informed decisions."},{"id":"ch06-013","term":"Revenue","definition":"Income or earnings of an organization."},{"id":"ch06-014","term":"Strategic planning","definition":"A process of creating a future plan based on defined objectives and outcomes for the organization."},{"id":"ch06-015","term":"Vision","definition":"An aspirational declaration of an organization’s future."}]},{"number":7,"title":"Chapter 7","cards":[{"id":"ch07-001","term":"Airborne contact","definition":"Occurs when a person inhales infected droplets that have become airborne (i.e., exposure to bacteria or virus through coughing and sneezing)."},{"id":"ch07-002","term":"Blood-borne pathogens","definition":"Pathogenic microorganisms that are present in human blood and can cause disease in humans. These pathogens include, but are not limited to, hepatitis B virus (HBV) and human immunodeficiency virus (HIV)."},{"id":"ch07-003","term":"Body substance isolation (BSI)","definition":"An approach to infection control expanding on the original concept of universal precautions. BSI covers all body substances (e.g., blood, urine, feces, tears) of people undergoing medical interventions, especially during out-of-hospital care of those who might be infected with infectious diseases, such as HIV or hepatitis."},{"id":"ch07-004","term":"Cirrhosis","definition":"Scarring of the liver."},{"id":"ch07-005","term":"Direct contact","definition":"Passing of an infectious substance from one person to another—for example, when infected blood from one coworker splashes into the eye of another coworker or when someone directly touches body fluids of an infected person (i.e., percutaneous or mucosal contact)."},{"id":"ch07-006","term":"Emesis","definition":"Vomiting."},{"id":"ch07-007","term":"Engineering controls","definition":"Means controls (e.g., sharps disposal containers, self-sheathing needles, or safer medical devices, such as sharps with engineered injury protections and needleless systems) that isolate or remove the blood-borne pathogens hazard from the workplace."},{"id":"ch07-008","term":"Exposure control plan (ECP)","definition":"Written plan that eliminates or minimizes employee exposure as defined by the Occupational Safety and Health Administration."},{"id":"ch07-009","term":"Exposure determination","definition":"Who is at risk based on job classification, where exposure to blood or OPIMs may occur without regard to the use of PPE."},{"id":"ch07-010","term":"Handwashing facility","definition":"A facility providing an adequate supply of running potable water, soap, and single-use towels or air-drying machines."},{"id":"ch07-011","term":"Hepatitis","definition":"Inflammation of the liver."},{"id":"ch07-012","term":"Human immunodeficiency virus (HIV)","definition":"A retrovirus that is the etiologic agent of acquired immunodeficiency syndrome (AIDS)."},{"id":"ch07-013","term":"Indirect contact","definition":"When a person touches an object that contains the blood or OPIM of an infected person, and that fluid then enters their body at a correct entry site (i.e., sharing items such as razors and toothbrushes)."},{"id":"ch07-014","term":"Microorganisms","definition":"Organisms of microscopic or submicroscopic size."},{"id":"ch07-015","term":"Occupational exposure","definition":"Reasonably anticipated contact of the skin, eye, or mucous membrane with blood or OPIMs that may result from the performance of the employee’s duties."},{"id":"ch07-016","term":"Other potentially infectious materials (OPIMs)","definition":"Other bodily fluids or tissues that have been infected with pathogens, including semen, vaginal secretions, cerebrospinal fluid, synovial fluid, pleural fluid, saliva, and other bodily fluids."},{"id":"ch07-017","term":"Personal protective equipment (PPE)","definition":"Specialized clothing or equipment worn by an employee for protection against a hazard. General work clothes (e.g., uniforms, pants, shirts, or blouses) not intended to function as protection against a hazard are not considered PPE."},{"id":"ch07-018","term":"Standard precautions (SPs)","definition":"Combine major features of universal precautions (UP) and body substance isolation (BSI) and are based on the principle that all blood, body fluids, secretions, excretions except for sweat, nonintact skin, and mucous membranes may contain transmissible infectious agents."},{"id":"ch07-019","term":"Universal precautions","definition":"Approach to infection control. According to the concept of universal precautions, all human blood and certain human body fluids are treated as if known to be infectious for HIV, HBV, and other blood-borne pathogens."},{"id":"ch07-020","term":"Vector-borne contact","definition":"Transmitted by an animal (i.e., exposure to infected animals such as dogs, raccoons, insects, and bats)."},{"id":"ch07-021","term":"Work practice controls","definition":"Controls that reduce the likelihood of exposure by altering the manner in which a task is performed (e.g., prohibiting recapping of needles by a two-handed technique)."}]},{"number":8,"title":"Chapter 8","cards":[{"id":"ch08-001","term":"Acclimatization","definition":"The process or result of becoming accustomed to a new climate or set of conditions; complex series of changes or adaptations that occur in response to heat stress in a controlled environment over the course of 7 to 14 days."},{"id":"ch08-002","term":"Baseline concussion testing","definition":"A series of physical and cognitive tests that measure healthy brain function before a sports season starts and prior to an injury occurring. The results of the baseline testing can be compared to test results postinjury to monitor recovery and return to play."},{"id":"ch08-003","term":"Core temperature","definition":"The temperature of the body, specifically in deep structures of the body, in comparison to temperatures of peripheral tissues."},{"id":"ch08-004","term":"Dehydration","definition":"Excessive loss of body water."},{"id":"ch08-005","term":"Electrocardiogram","definition":"A test that measures the electrical activity of the heartbeat."},{"id":"ch08-006","term":"Ergonomics","definition":"The science concerned with fitting a job to a person’s anatomical, physiological, and psychological characteristics to enhance human efficiency and well-being."},{"id":"ch08-007","term":"Euhydration","definition":"Normal state of body water content; absence of absolute or relative hydration or dehydration."},{"id":"ch08-008","term":"Gastric emptying","definition":"The time it takes for food and fluids to leave the stomach."},{"id":"ch08-009","term":"Hydration","definition":"The process of replacing water in the body."},{"id":"ch08-010","term":"Hyperhydration","definition":"Excessive water in the body."},{"id":"ch08-011","term":"Hyperthermia","definition":"Elevated core temperature."},{"id":"ch08-012","term":"Hyponatremia","definition":"Low blood sodium levels."},{"id":"ch08-013","term":"Hypothermia","definition":"Core temperature below 35°C (95°F)."},{"id":"ch08-014","term":"Preparticipation physical examination","definition":"Physical examination to help assess and maintain the health and safety of athletes; sport physicals."},{"id":"ch08-015","term":"Prevention","definition":"The action taken to decrease the chance of getting a disease, condition, or injury."},{"id":"ch08-016","term":"Relative humidity","definition":"The amount of water vapor present in air; expressed as a percentage of the amount needed for saturation at the same temperature."},{"id":"ch08-017","term":"Shivering","definition":"Involuntary response to decreased core temperature in an effort to generate heat through muscle contractions."},{"id":"ch08-018","term":"Thermal gradient","definition":"The difference between the temperature of the environment and the temperature of the body."},{"id":"ch08-019","term":"Thermoregulation","definition":"The body’s ability to maintain a normal core temperature, which is rigorously maintained at approximately 37°C (99°F)."}]},{"number":9,"title":"Chapter 9","cards":[{"id":"ch09-001","term":"Aerobic","definition":"A process that requires oxygen, such as cardiorespiratory exercise."},{"id":"ch09-002","term":"Autonomic nervous system","definition":"A part of the nervous system that controls resting functions, such as heart rate, respiratory rate, and digestion."},{"id":"ch09-003","term":"Basal metabolic rate","definition":"The minimum daily calories required to maintain normal resting bodily functions; does not include energy for daily activities or exercise."},{"id":"ch09-004","term":"Body composition","definition":"The proportions of fat and fat-free mass in the body."},{"id":"ch09-005","term":"Cardiorespiratory fitness (CRF)","definition":"The ability to perform exercise involving large muscle groups at moderate to high intensities for prolonged periods.87"},{"id":"ch09-006","term":"Contraindication","definition":"Any symptom or circumstance indi­cating the inappropriateness of an otherwise advisable treatment, procedure, or exercise."},{"id":"ch09-007","term":"Dose–response relationship","definition":"The relationship between the quantity of a substance or exposure (i.e., amount of exercise) and its overall effect on the body."},{"id":"ch09-008","term":"Dual-energy X-ray absorptiometry (DEXA)","definition":"The use of low-dose X-rays to measure bone mineral density and body composition."},{"id":"ch09-009","term":"Flexibility","definition":"The ability of a joint to move through a full range of motion."},{"id":"ch09-010","term":"Gold standard","definition":"Considered the best method of measurement, based on validity and reliability."},{"id":"ch09-011","term":"Hemoglobin A1c","definition":"Glycosylated hemoglobin; a measure of the average blood glucose level over the lifetime of a red blood cell, approximately 2 to 3 months."},{"id":"ch09-012","term":"Hydrodensitometry","definition":"Also known as underwater weighing; uses water displacement to measure body volume and thus body composition."},{"id":"ch09-013","term":"Hypertension","definition":"Also known as high blood pressure, it causes the heart to contract against higher levels of pressure in the blood vessels. Diagnosed with resting blood pressure above 130/80."},{"id":"ch09-014","term":"Impedance","definition":"A measure of the amount of opposition to the flow of a current in the body; used during bioelectrical impedance to estimate body fat."},{"id":"ch09-015","term":"Indirect calorimetry","definition":"Measurement of oxygen consumption and carbon dioxide production to determine substrate use and caloric burn."},{"id":"ch09-016","term":"Insulin resistance","definition":"The body’s response to insulin is impaired, resulting in elevated levels of glucose in the blood."},{"id":"ch09-017","term":"Lifestyle disease","definition":"Diseases caused by unhealthy lifestyle habits, such as inactivity, poor sleep, smoking, and poor nutrition."},{"id":"ch09-018","term":"Metabolic equivalent","definition":"MET, where 1 MET is the energy expenditure of sitting."},{"id":"ch09-019","term":"Mortality","definition":"Relating to death, specifically the risk of death attributable to a disease."},{"id":"ch09-020","term":"Muscular fitness","definition":"A composite of muscular strength, endurance, and power."},{"id":"ch09-021","term":"Neuromotor","definition":"Training that incorporates motor skills, such as balance, coordination, and proprioceptive exercises."},{"id":"ch09-022","term":"Overload","definition":"A gradual increase in stress (i.e., exercise) must be applied to the body to continue adaptations."},{"id":"ch09-023","term":"Plethysmography","definition":"A body composition technique using air displacement for measurement of body volume and thus body composition; typically conducted with the Bod Pod."},{"id":"ch09-024","term":"Progression","definition":"A systematic increase in workload (duration or intensity) to increase fitness levels."},{"id":"ch09-025","term":"Proprioception","definition":"Also known as kinesthesia; the ability to identify a body’s position in space."},{"id":"ch09-026","term":"Resistance training","definition":"Also known as strength training or weightlifting, it is an exercise intended to improve muscular strength and endurance."},{"id":"ch09-027","term":"Skinfolding","definition":"A technique that estimates body fat percentage from several thickness folds of skin and subcutaneous fat across the body."},{"id":"ch09-028","term":"Specificity","definition":"Adaptations of the body to exercise are specific to the type of training undertaken."},{"id":"ch09-029","term":"Thermoregulation","definition":"The body’s ability to maintain a normal core temperature, which is rigorously maintained at approximately 37°C (99°F)."},{"id":"ch09-030","term":"Type 2 diabetes","definition":"A chronic medical condition where the body does not produce enough insulin, resulting in elevated blood sugar levels."},{"id":"ch09-031","term":"VO2max","definition":"A measure of the maximal volume of oxygen the lungs can take in, and the working muscles can distribute and use."}]},{"number":10,"title":"Chapter 10","cards":[{"id":"ch10-001","term":"Adenosine triphosphate (ATP)","definition":"A molecule that carries energy within cells. It is the main energy currency of the cell."},{"id":"ch10-002","term":"Amino acids","definition":"The individual building blocks for protein structure. The type of protein made and its function are determined by the sequence and types of amino acids present in its structure."},{"id":"ch10-003","term":"Anaerobic","definition":"Relating to, involving, or requiring an absence of free oxygen."},{"id":"ch10-004","term":"Anemia","definition":"A condition in which one’s body lacks enough healthy red blood cells to carry adequate oxygen to the tissues, which can lead to extreme fatigue."},{"id":"ch10-005","term":"Antioxidants","definition":"Substances that can prevent or slow damage to cells caused by free radicals."},{"id":"ch10-006","term":"Antithrombotic","definition":"An agent that reduces the formation of blood clots (thrombi)."},{"id":"ch10-007","term":"Biological value","definition":"A measure of the efficiency of the protein in food for the maintenance and growth of bodily tissues."},{"id":"ch10-008","term":"Carbohydrate loading","definition":"A practice that competitive and elite athletes use to supersaturate their muscles with optimal glycogen levels."},{"id":"ch10-009","term":"Certified specialist in sports dietetics (CSSD)","definition":"An RD with additional education and specific knowledge, skills, and expertise for competency in sports dietetics practice."},{"id":"ch10-010","term":"Complex carbohydrates","definition":"Long chains of carbohydrates containing more than 10 monosaccharide units. Whole grains, starchy vegetables, and legumes are examples of complex carbohydrates."},{"id":"ch10-011","term":"Dietary supplements","definition":"A product taken orally that contains one or more ingredients (such as vitamins or amino acids) that are intended to supplement one’s diet and are not considered food."},{"id":"ch10-012","term":"Docosahexaenoic acid (DHA)","definition":"An omega-3 fatty acid that is a primary structural component of the human brain, cerebral cortex, skin, and retina."},{"id":"ch10-013","term":"Eicosapentaenoic acid (EPA)","definition":"An omega-3 fatty acid found in the flesh of cold-water fish."},{"id":"ch10-014","term":"Electrolyte","definition":"Micronutrients that separate into ions in solution, thus acquiring the capacity to conduct electricity. The main electrolytes that are mandatory for optimal cellular hydration and function are sodium, potassium, chloride, calcium, magnesium, and phosphate."},{"id":"ch10-015","term":"Ergogenic aid","definition":"Training technique, mechanical device, nutritional ingredient or practice, pharmacological method, or psychological technique that can improve exercise performance capacity or enhance training adaptations."},{"id":"ch10-016","term":"Fatty acids","definition":"Molecules that are long chains of lipid-carboxylic acid found in fats and oils."},{"id":"ch10-017","term":"Female athlete triad","definition":"Condition related to low energy availability and variations and degrees of physiological changes associated with menstrual cycle disruption; ultimately, may cause bone mineral losses, stress fractures, or osteoporosis."},{"id":"ch10-018","term":"Free radicals","definition":"Unstable molecules the body produces as a reaction to environmental and other pressures."},{"id":"ch10-019","term":"Glucose","definition":"A simple sugar that is an important energy source in living organisms; a component of many carbohydrates."},{"id":"ch10-020","term":"Glycogen","definition":"A long chain of glucose molecules linked together; the main form from which energy is derived in working muscles."},{"id":"ch10-021","term":"Hypertrophy","definition":"Increase in bulk."},{"id":"ch10-022","term":"Low energy availability","definition":"The state of lacking enough calories (energy) for both the body’s requirements and exercise."},{"id":"ch10-023","term":"Macronutrients","definition":"A type of food (e.g., fat, protein, and carbohydrate) required in large amounts in the diet."},{"id":"ch10-024","term":"Metabolism","definition":"Entirety of all chemical processes that convert the essential nutrients we consume in our food to energy in our bodies."},{"id":"ch10-025","term":"Micronutrients","definition":"Vitamins and minerals that must be obtained from our food to maintain optimal health."},{"id":"ch10-026","term":"Minerals","definition":"A chemical element required as an essential nutrient by organisms to perform functions necessary for life."},{"id":"ch10-027","term":"Nutrient density","definition":"Food that is high in nutrients but relatively low in calories. Nutrient-dense foods contain vitamins, minerals, complex carbohydrates, lean protein, and healthy fat."},{"id":"ch10-028","term":"Nutrition","definition":"Act or process of nourishing or being nourished; specifically, the sum of the processes by which a person takes in and uses food substances that are necessary for human function."},{"id":"ch10-029","term":"Phytonutrients","definition":"A substance found in certain plants that is believed to be beneficial to human health and helps prevent various diseases."},{"id":"ch10-030","term":"Registered dietitian (RD)","definition":"Food and nutrition experts who have met the criteria from the Commission on Dietetic Registration (CDR) to earn the RD credential."},{"id":"ch10-031","term":"Relative energy deficiency in sport (RED-S)","definition":"Impaired physiological functioning caused by relative energy deficiency; includes, but is not limited to, impairments of metabolic rate, menstrual function, bone health, immunity, protein synthesis, and cardiovascular health."},{"id":"ch10-032","term":"Simple carbohydrates","definition":"Formed from 10 or fewer monosaccharides. Dairy products, fruit, and sucrose are examples of simple carbohydrates."},{"id":"ch10-033","term":"Triglycerides","definition":"The major form of fat stored by the body. Triglycerides serve as the backbone for many types of lipids (fats). Triglycerides come from the food we eat and are also produced by the body."},{"id":"ch10-034","term":"Vitamins","definition":"Organic compounds that are needed in small quantities to sustain life and help the body grow and develop normally."}]},{"number":11,"title":"Chapter 11","cards":[{"id":"ch11-001","term":"Acute anterior compartment syndrome","definition":"A serious, often limb-threatening, condition where pressure builds up in the anterior compartment of the lower leg. The increasing pressure affects the neurovascular structures in the lower leg. Causes of acute anterior compartment syndrome in the lower leg include a direct blow or fracture."},{"id":"ch11-002","term":"Commotio cordis","definition":"Sudden arrhythmic death caused by an impact to the chest wall. It is mostly seen in athletes between the ages of 8 and 18 who play sports with projectiles, such as baseballs, hockey pucks, or lacrosse balls. The timing and location of the impact are important factors in determining whether or not an athlete will have this condition. Immediate CPR and defibrillation are imperative for preventing death; even with CPR and AED use, survival is rare.89"},{"id":"ch11-003","term":"Product liability","definition":"The responsibility of the manufacturer, distributor, and seller of a product to deliver products free of defects that could cause harm and to compensate for any injury caused by defective merchandise."},{"id":"ch11-004","term":"Protective equipment","definition":"Various items worn to reduce the risk of injury from sport or activity."}]},{"number":12,"title":"Chapter 12","cards":[{"id":"ch12-001","term":"Antagonist muscle","definition":"A muscle with the opposite action of the prime mover."},{"id":"ch12-002","term":"Density","definition":"The weight of a product as compared to its size. Typically, products that boast higher density offer greater protection and are more resistant to deformation and impact."},{"id":"ch12-003","term":"Mallet finger","definition":"Rupture of one or more of the distal extensor tendons of the hand or an avulsion of the extensor tendon from the distal phalanx of the thumb or finger."},{"id":"ch12-004","term":"Product liability","definition":"The responsibility of the manufacturer, distributor, and seller of a product to deliver products free of defects that could cause harm and to compensate for any injury caused by defective merchandise that they have provided for sale."},{"id":"ch12-005","term":"Prophylactic procedures","definition":"Various techniques used to guard or protect a body part from injury or reinjury."},{"id":"ch12-006","term":"Protective equipment","definition":"Various items worn to help reduce the risk of injury from sport or activity."},{"id":"ch12-007","term":"Rigidity","definition":"Also known as stiffness; the amount of bending or compression that occurs in response to a measured amount of applied stress."},{"id":"ch12-008","term":"Tensile strength","definition":"Measurement of how much tensile force a material can withstand before it fails. This is often reported as pounds per square inch."}]},{"number":13,"title":"Chapter 13","cards":[{"id":"ch13-001","term":"Catastrophic injury","definition":"Fatalities, permanent disability injuries, serious injuries (fractured neck or serious head injury), even though the athlete has a full recovery, temporary or transient paralysis, heat stroke due to exercise, or sudden cardiac arrest."},{"id":"ch13-002","term":"Chain of command","definition":"The official hierarchy of authority that dictates who is in charge of whom and of whom permission must be asked."},{"id":"ch13-003","term":"Chief complaint","definition":"The main reason the patient is seeing the athletic trainer; the patient’s primary complaint."},{"id":"ch13-004","term":"Emergency medical services (EMS)","definition":"A system that represents the combined efforts of several professionals and agencies to provide prehospital emergency care to the sick and injured."},{"id":"ch13-005","term":"Emergency medical technician (EMT)","definition":"Someone trained in basic life support, including AED use, airway adjuncts, and assisting patients with certain medications."},{"id":"ch13-006","term":"Mass casualty incident","definition":"Any emergency situation where the number of patients outnumbers the resources (e.g., personnel, equipment) available."},{"id":"ch13-007","term":"Medical control","definition":"Usually a physician at a local hospital who directs medical care or decisions for EMS providers; this direction can be done in real time over the radio or cell phone during a call, and it also includes preestablished protocols that EMS personnel must follow."},{"id":"ch13-008","term":"Medical emergency","definition":"Emergencies that are not caused by an outside force, illness, or condition."},{"id":"ch13-009","term":"Paramedic","definition":"Someone who has extensive training in advanced life support, including intubation, emergency pharmacology, cardiac monitoring, and other advanced assessment and treatment skills."},{"id":"ch13-010","term":"Triage","definition":"The process of sorting patients based on the severity of the injury and medical need to establish treatment and transportation priorities."}]},{"number":14,"title":"Chapter 14","cards":[{"id":"ch14-001","term":"Agonal breathing","definition":"Labored, gasping breaths; the body’s final attempt to sustain life."},{"id":"ch14-002","term":"Airway adjuncts","definition":"Devices used once an airway has been established to maintain an open airway."},{"id":"ch14-003","term":"Altered mental status (AMS)","definition":"General term used to describe various changes in a patient’s mental functioning that can range from slight confusion to coma. These can include signs and symptoms such as confusion, amnesia, disorientation, and unusual or strange behavior."},{"id":"ch14-004","term":"Anaphylaxis","definition":"A severe, potentially life-threatening allergic reaction."},{"id":"ch14-005","term":"Approximation","definition":"Bringing tissue edges together for suturing."},{"id":"ch14-006","term":"Aseptic technique","definition":"Practices and procedures to prevent contamination from pathogens."},{"id":"ch14-007","term":"Aspiration","definition":"The accidental sucking in of food particles or fluids into the lungs."},{"id":"ch14-008","term":"AVPU scale","definition":"An acronym for “alert, verbal, pain, unresponsive”; a system to measure and record a patient’s level of consciousness."},{"id":"ch14-009","term":"Bradycardia","definition":"Heart rate that is slower than normal."},{"id":"ch14-010","term":"Capillary refill","definition":"The time it takes for color to return to an external capillary bed after pressure is applied to cause blanching; usually less than 2 seconds."},{"id":"ch14-011","term":"Cerebrospinal fluid (CSF)","definition":"Clear, colorless body fluid found around the brain and spinal cord."},{"id":"ch14-012","term":"Chief complaint","definition":"The main reason the patient is seeing the athletic trainer; the patient’s primary complaint."},{"id":"ch14-013","term":"Cyanosis","definition":"Bluish or purplish discoloration of the skin or mucous membranes due to the tissues near the skin surface having low oxygen saturation."},{"id":"ch14-014","term":"Debride","definition":"To remove dead, contaminated, or adherent tissue or foreign material from a wound."},{"id":"ch14-015","term":"Decerebrate","definition":"Abnormal body posture that involves holding the arms and legs straight out, plantarflexing the feet, and arching the head and neck backward. The muscles are tightened and held rigidly."},{"id":"ch14-016","term":"Decorticate","definition":"Abnormal posturing in which a person is stiff with flexed arms, clenched fists, and legs held out straight. The arms are flexed in toward the body, and the wrists and fingers are bent and held on the chest."},{"id":"ch14-017","term":"Diaphoretic","definition":"Excessive sweating for no apparent reason."},{"id":"ch14-018","term":"Diastolic","definition":"Minimum arterial pressure during relaxation and dilatation of the ventricles of the heart when the ventricles fill with blood."},{"id":"ch14-019","term":"Dyspnea","definition":"Shortness of breath."},{"id":"ch14-020","term":"Endotracheal intubation","definition":"Procedure by which a tube is inserted through the mouth into the trachea to maintain the patient’s airway."},{"id":"ch14-021","term":"Glasgow Coma Scale (GCS)","definition":"Common scoring system used to describe the level of consciousness in a person following a traumatic brain injury. Summation of scores for eye, verbal, and motor responses."},{"id":"ch14-022","term":"Head-tilt/chin-lift maneuver","definition":"Procedure used to prevent the tongue from obstructing the airway. The maneuver is performed by tilting the patient’s head backward by applying pressure to the forehead and the chin. It is the preferred method of opening the airway."},{"id":"ch14-023","term":"Hyperglycemia","definition":"High blood sugar."},{"id":"ch14-024","term":"Hypertension","definition":"High blood pressure."},{"id":"ch14-025","term":"Hypoglycemia","definition":"Low blood sugar."},{"id":"ch14-026","term":"Hypoperfusion","definition":"Inadequate delivery of vital oxygen and nutrients to body tissues."},{"id":"ch14-027","term":"Hypotension","definition":"Low blood pressure."},{"id":"ch14-028","term":"Hypovolemic","definition":"State of decreased blood volume or diminished body fluid."},{"id":"ch14-029","term":"Hypoxia","definition":"Deficiency in the amount of oxygen that reaches the tissues of the body."},{"id":"ch14-030","term":"Jaundice","definition":"Condition in which the skin, whites of the eyes, and mucous membranes turn yellow because of a high level of bilirubin."},{"id":"ch14-031","term":"Jaw-thrust technique","definition":"Procedure used to prevent the tongue from obstructing the airway. The jaw-thrust maneuver is used on patients with a suspected cervical spine injury because it allows for the athletic trainer to clear the tongue from the airway with minimal neck movement. It is performed by placing the fingers under the lower jaw to physically push it upward to open the mouth."},{"id":"ch14-032","term":"Jugular vein distention","definition":"Bulging of the neck veins caused by increased pressure in the superior vena cava."},{"id":"ch14-033","term":"Malaise","definition":"Feeling of general discomfort, uneasiness, or pain; often the first sign of an infection or other condition."},{"id":"ch14-034","term":"Mechanism of injury (MOI)","definition":"Manner by which the injury occurred."},{"id":"ch14-035","term":"Myoclonus","definition":"Sudden, involuntary jerking of a muscle or group of muscles."},{"id":"ch14-036","term":"Nature of illness (NOI)","definition":"For nontraumatic conditions, the manner by which the condition or illness developed."},{"id":"ch14-037","term":"Perfusion","definition":"The passage of fluid through the circulatory system to organs or tissues, usually referring to the delivery of blood to an area."},{"id":"ch14-038","term":"Personal protective equipment (PPE)","definition":"Protective clothing, goggles, gloves, and equipment that protect the athletic trainer from exposure to infection or disease from contact with a patient."},{"id":"ch14-039","term":"Shock","definition":"Critical condition that is brought on by a sudden drop in blood flow through the body. The circulatory system fails to maintain adequate blood flow, decreasing the delivery of oxygen and nutrients to vital organs."},{"id":"ch14-040","term":"Spinal motion restriction (SMR)","definition":"Attempting to maintain the spine in anatomic alignment (spinal neutral) and minimizing gross movement irrespective of adjuncts or devices."},{"id":"ch14-041","term":"Systolic","definition":"Pressure in the arteries during the contraction of the ventricles."},{"id":"ch14-042","term":"Tachycardia","definition":"Heart rate is faster than normal."},{"id":"ch14-043","term":"Thready pulse","definition":"A scarcely perceptible, often rapid pulse that feels like a fine, mobile thread under a palpating finger."},{"id":"ch14-044","term":"Triaging","definition":"The sorting of multiple patients according to the urgency of their need for care."}]},{"number":15,"title":"Chapter 15","cards":[{"id":"ch15-001","term":"Avascular necrosis","definition":"Without blood supply."},{"id":"ch15-002","term":"Bone-building years","definition":"Time during which peak bone mass is developed, generally considered to take place in women from the late teen years to the late 20s."},{"id":"ch15-003","term":"Bone stress response","definition":"Swelling within the bone as a response to undue stresses."},{"id":"ch15-004","term":"Bursitis","definition":"Injury resulting in inflammation of a bursa."},{"id":"ch15-005","term":"Central nervous system (CNS)","definition":"Portion of the nervous system made up of the brain and spinal cord."},{"id":"ch15-006","term":"Contact healing","definition":"A form of primary healing where the bone is held tightly together."},{"id":"ch15-007","term":"Cortical bone","definition":"Also known as compact bone; the dense bone responsible for skeletal mass that is imperative to body structure and weight-bearing."},{"id":"ch15-008","term":"Diaphysis","definition":"The shaft of long bones."},{"id":"ch15-009","term":"Epiphyseal plate","definition":"Also known as the growth plate; a hyaline cartilage plate found in the metaphysis that remains open during bone-growing years."},{"id":"ch15-010","term":"Epiphysis","definition":"The end portion of a long bone."},{"id":"ch15-011","term":"Fibroblastic proliferation","definition":"The haphazard laying down of collagen tissue during the repair process following soft tissue injury."},{"id":"ch15-012","term":"Gap healing","definition":"A form of secondary healing where bone must form across an injured area that is not approximated."},{"id":"ch15-013","term":"Heterotopic ossification","definition":"Benign process characterized by heterotopic ossification, or bone formation, within large muscles."},{"id":"ch15-014","term":"Hydroxyapatite","definition":"A mineral that is the main inorganic constituent of bone."},{"id":"ch15-015","term":"Mechanism of injury","definition":"Manner by which damage to soft tissue occurs."},{"id":"ch15-016","term":"Metaphysis","definition":"Narrow portion of long bone that separates the epiphysis from the diaphysis."},{"id":"ch15-017","term":"Muscular dystrophy","definition":"Hereditary condition marked by progressive wasting of muscles."},{"id":"ch15-018","term":"Myasthenia gravis","definition":"Rare, chronic autoimmune disease marked by muscular weakness without atrophy."},{"id":"ch15-019","term":"Myelinated","definition":"Nerve fiber enclosed in a sheath that improves impulse conduction."},{"id":"ch15-020","term":"Ossification","definition":"Natural process of bone formation."},{"id":"ch15-021","term":"Osteoblast","definition":"Cell that secretes the matrix necessary for bone formation."},{"id":"ch15-022","term":"Osteoclast","definition":"Cell that absorbs bone tissue during bone growth and healing."},{"id":"ch15-023","term":"Osteocytes","definition":"Cell formed when an osteoblast becomes embedded in the matrix it has secreted."},{"id":"ch15-024","term":"Osteokinematics","definition":"Movement of long bones that produces motion."},{"id":"ch15-025","term":"Osteopenia","definition":"Mild thinning of bone mass; a precursor to osteoporosis."},{"id":"ch15-026","term":"Osteoporosis","definition":"Medical condition in which bones become brittle and fragile due to loss of tissue; typically results from deficiency in calcium or vitamin D or hormonal changes."},{"id":"ch15-027","term":"Pathologic fractures","definition":"Fracture caused by disease rather than trauma."},{"id":"ch15-028","term":"Pathophysiology","definition":"The disordered physiological processes associated with disease or injury."},{"id":"ch15-029","term":"Peripheral nervous system (PNS)","definition":"Portion of the nervous system outside the brain and spinal cord."},{"id":"ch15-030","term":"Primary healing","definition":"Wound or tissue healing where scar tissue does not have to fill a gap in the injured tissue."},{"id":"ch15-031","term":"Relative energy deficiency in sports (RED-S)","definition":"Impaired physiological functioning caused by relative energy defi­ciency; includes impairments of metabolic rate, menstrual function, bone health, immunity, protein synthesis, and cardiovascular health."},{"id":"ch15-032","term":"Salter-Harris fracture","definition":"Fracture involving the epiphyseal plate."},{"id":"ch15-033","term":"Schwann cells","definition":"Myelin-secreting glial cells that form the myelin sheath around the axon."},{"id":"ch15-034","term":"Secondary healing","definition":"Wound or tissue healing where the wound edges cannot be approximated, and granulation tissue must fill the gap in the wound."},{"id":"ch15-035","term":"Stress fracture","definition":"A fracture of bone caused by repeated mechanical stresses."},{"id":"ch15-036","term":"Stress syndrome","definition":"Inflammatory process of bone caused by repeated mechanical stresses; often precedes stress fracture."},{"id":"ch15-037","term":"Stress tolerance","definition":"The ability to withstand stress without breaking."},{"id":"ch15-038","term":"Subchondral","definition":"Layer of bone found just below the cartilage that acts as a shock absorber in weight-bearing joints."},{"id":"ch15-039","term":"Tendinopathy","definition":"Injury to a tendon; for example, tendinitis, tendinosis, and tenosynovitis."},{"id":"ch15-040","term":"Trabecular bone","definition":"Also known as spongy bone; porous bone containing red bone marrow found at the ends of long bones."},{"id":"ch15-041","term":"Viscoelastic","definition":"Exhibiting both viscous and elastic components when deformed."},{"id":"ch15-042","term":"Wallerian degeneration","definition":"Degeneration of a nerve fiber that occurs distal to the site of injury when the nerve fiber is cut or crushed."},{"id":"ch15-043","term":"Wolff’s law","definition":"A law that states that tissue, particularly bone, will adapt to the loads under which it is placed."}]},{"number":16,"title":"Chapter 16","cards":[{"id":"ch16-001","term":"Activities of daily living (ADLs)","definition":"Tasks that enable people to meet their basic needs. Examples include eating, dressing, hygiene, housecleaning, and shopping."},{"id":"ch16-002","term":"Acute","definition":"A condition or injury with a rapid onset and a short course, usually resulting from a single mechanism of injury; not chronic."},{"id":"ch16-003","term":"Alleviation","definition":"Something that lessens the signs and symptoms of a condition or injury."},{"id":"ch16-004","term":"Anatomical position","definition":"The reference position for the body for nomenclature and measurements. The position is the body standing erect, with the arms at the side and the palms facing forward."},{"id":"ch16-005","term":"Anesthesia","definition":"The absence of sensation."},{"id":"ch16-006","term":"Antalgic gait","definition":"Gait in which the patient has pain during the stance phase and so remains on the painful leg for as short a time as possible."},{"id":"ch16-007","term":"Arthrokinematics","definition":"Description of the movement of the joint surfaces when a bone moves through a range of motion."},{"id":"ch16-008","term":"Assessment","definition":"The process by which the patient’s condition or injury is appraised or evaluated. It involves collecting information from the patient’s medical history, reported symptoms, and laboratory or diagnostic results."},{"id":"ch16-009","term":"Auscultation","definition":"The process of listening to sounds within the body; done with a stethoscope."},{"id":"ch16-010","term":"Baseline","definition":"Initial values or measurements (e.g., vital signs, ROM) to which subsequent measurements can be compared."},{"id":"ch16-011","term":"Bilateral","definition":"Both sides; during examination, the injured or affected area is compared with the noninjured side of the body."},{"id":"ch16-012","term":"Break test","definition":"Test for strength completed by having the athletic trainer apply resistance while the patient holds a contraction; typically performed in the mid-range of motion."},{"id":"ch16-013","term":"Chief complaint","definition":"The main reason the patient is seeing the athletic trainer; the patient’s primary complaint."},{"id":"ch16-014","term":"Chronic","definition":"A condition or injury with a long duration or slow progression, usually resulting from repetitive stress; the opposite of acute."},{"id":"ch16-015","term":"Clinical diagnosis","definition":"The use of clinical methods to establish the cause and nature of a patient’s condition or injury and the subsequent functional impairment caused by the pathology."},{"id":"ch16-016","term":"Clinical prediction rules","definition":"Guidelines that consider various components of the history, physical examination, and basic laboratory results to inform the diagnosis, prognosis, or treatment or intervention of a patient."},{"id":"ch16-017","term":"Clonus","definition":"Rhythmic alternation of muscular contractions caused by a hyperactive stretch reflex from an upper motor neuron lesion."},{"id":"ch16-018","term":"Concentric contraction","definition":"A muscle contraction where the fibers shorten as the muscle contracts. The opposite of an eccentric contraction."},{"id":"ch16-019","term":"Contraindication","definition":"Any symptom or circumstance indicating the inappropriateness of an otherwise advisable treatment or procedure."},{"id":"ch16-020","term":"Crepitus","definition":"A grating or crackling sound and sensation created during movement due to irregularities between structures; occurs from the ends of a bone fracture rubbing or when there is air present in spaces where it should not be (e.g., pleural space)."},{"id":"ch16-021","term":"Dermatomes","definition":"A delineated area of the skin innervated by a single nerve root. Each cord segment has a represented skin area."},{"id":"ch16-022","term":"Differential diagnosis","definition":"Identification of a condition or injury by comparison of the symptoms of two or more similar conditions or injuries."},{"id":"ch16-023","term":"Eccentric contraction","definition":"A muscle contraction where the fibers lengthen as the muscle contracts. The opposite of a concentric contraction."},{"id":"ch16-024","term":"Ecchymosis","definition":"Skin discoloration; often black and blue that later changes to green and yellow."},{"id":"ch16-025","term":"End feel","definition":"Quality of the sensation felt when stressing a joint at the end range of motion."},{"id":"ch16-026","term":"Evaluation","definition":"The systematic process that allows the athletic trainer to make a clinical judgment or diagnosis."},{"id":"ch16-027","term":"Examination","definition":"The act or process of inspecting the body to determine the presence or absence of an injury or pathology."},{"id":"ch16-028","term":"Goniometer","definition":"Apparatus used to measure range of motion and joint angles. Different sizes and types of goniometers are available to measure different joints."},{"id":"ch16-029","term":"Hemorrhage","definition":"Abnormal and severe internal or external bleeding."},{"id":"ch16-030","term":"Hyperesthesia","definition":"Heightened or increased sensation."},{"id":"ch16-031","term":"Hypermobility","definition":"Excessive joint play (movement) that permits increased mobility."},{"id":"ch16-032","term":"Hypoesthesia","definition":"Decreased sensation."},{"id":"ch16-033","term":"Hypomobility","definition":"Restricted joint movement (play) that limits normal range of motion; the opposite of hypermobility."},{"id":"ch16-034","term":"Instability","definition":"The lack of ability to maintain alignment of bony segments, usually due to a torn or lax ligament and weak muscles."},{"id":"ch16-035","term":"Isometric contraction","definition":"Muscle contraction in a fixed position with no shortening or lengthening of the muscle fibers."},{"id":"ch16-036","term":"Isotonic contraction","definition":"Muscle contraction with shortening or lengthening of the muscle fibers while the tension or load remains the same throughout. Concentric and eccentric contractions are isotonic contractions."},{"id":"ch16-037","term":"Laxity","definition":"Increased joint movement."},{"id":"ch16-038","term":"Manual muscle test (MMT)","definition":"A technique for estimating the relative strength of a specific muscle."},{"id":"ch16-039","term":"Mechanism of injury (MOI)","definition":"Manner by which the injury occurred."},{"id":"ch16-040","term":"Myotome","definition":"Muscle or muscle group innervated by a single nerve root."},{"id":"ch16-041","term":"Nature of illness (NOI)","definition":"For nonorthopedic conditions, the manner by which the condition or illness developed."},{"id":"ch16-042","term":"Osteokinematics","definition":"Movement of long bones that produces motion."},{"id":"ch16-043","term":"Outcome measures","definition":"The instrument used to study the end result of health care services; these measures take patient’s experiences, preferences, and values into account and help integrate evidence-based practice into athletic trainers’ clinical practice."},{"id":"ch16-044","term":"Palliation","definition":"Something that reduces or relieves the pain or other symptoms without curing the condition."},{"id":"ch16-045","term":"Paresthesia","definition":"Abnormal sensations such as tingling, prickling, and numbness."},{"id":"ch16-046","term":"Pitting edema","definition":"Swelling, usually in the extremities, that when pressed will maintain the depression created for some time."},{"id":"ch16-047","term":"Point tenderness","definition":"Localized sore spot identified during palpation."},{"id":"ch16-048","term":"Provocation","definition":"Something that increases or aggravates the signs and symptoms of a condition or injury."},{"id":"ch16-049","term":"Referral","definition":"The practice of sending a patient to another health care provider for consultation or care; delegation of care."},{"id":"ch16-050","term":"Reflex","definition":"An involuntary response to a stimulus. Reflexes are specific and predictable; in this case, they are caused by stimulation of tendons."},{"id":"ch16-051","term":"Signs","definition":"Objective evidence or manifestation of a condition or injury."},{"id":"ch16-052","term":"Sports-related concussion (SRC)","definition":"A traumatic brain injury induced by biomechanical forces with several common features that may be used in clinically defining the nature of the injury."},{"id":"ch16-053","term":"Symptoms","definition":"Any perceived subjective change related to the condition or injury reported by the patient."},{"id":"ch16-054","term":"Trigger point","definition":"An area in the muscle or fascia that, when stimulated, will cause pain that typically radiates; there may be a palpable nodule present. Trigger points are not caused by acute trauma."}]},{"number":17,"title":"Chapter 17","cards":[{"id":"ch17-001","term":"Computed tomography (CT)","definition":"A radiographic study that uses ionizing radiation and the principles of tomography to make a series of three-dimensional cross-sectional images that are stored and reconstructed by a computer."},{"id":"ch17-002","term":"Diagnostic medical sonography (DMS)","definition":"An imaging and therapeutic modality that images or treats deep structures of the body by measuring and recording the reflection of high-frequency sound waves."},{"id":"ch17-003","term":"Magnetic resonance imaging (MRI)","definition":"An imaging technique that uses a strong magnetic field and radio waves to produce cross-sectional images of the body."},{"id":"ch17-004","term":"Nuclear medicine","definition":"A discipline that uses radioactive isotopes in the diagnosis and treatment of disease, including many types of cancers; heart disease; gastrointestinal, endocrine, and neurological disorders; and other abnormalities within the body."},{"id":"ch17-005","term":"Radiographic image","definition":"Also called a radiograph or X-ray; an image obtained through the use of ionizing radiation (X-rays) in combination with an image receptor (either film or digital)."},{"id":"ch17-006","term":"Radiologist","definition":"A physician specifically trained to supervise and interpret radiology examinations."}]},{"number":18,"title":"Chapter 18","cards":[{"id":"ch18-001","term":"Aneurysm","definition":"Localized enlargement of an arterial wall."},{"id":"ch18-002","term":"Anosmia","definition":"Loss of smell."},{"id":"ch18-003","term":"Apnea","definition":"Temporary cessation of breathing."},{"id":"ch18-004","term":"Arrhythmia","definition":"Irregular heartbeat."},{"id":"ch18-005","term":"Arthralgia","definition":"Joint pain."},{"id":"ch18-006","term":"Blepharospasm","definition":"Involuntary eyelid closure."},{"id":"ch18-007","term":"Diaphoresis","definition":"Unusual degree of sweating."},{"id":"ch18-008","term":"Dyspnea","definition":"Difficulty breathing."},{"id":"ch18-009","term":"Dysrhythmia","definition":"Abnormal physiological rhythm."},{"id":"ch18-010","term":"Empiric","definition":"Anticipated or likely."},{"id":"ch18-011","term":"Endemic transmission","definition":"Transmission at a predictable rate."},{"id":"ch18-012","term":"Epiphora","definition":"Excessive eye watering."},{"id":"ch18-013","term":"Erythema","definition":"Superficial reddening of the skin."},{"id":"ch18-014","term":"Hemolytic","definition":"Destruction of red blood cells."},{"id":"ch18-015","term":"Hematochezia","definition":"Vomiting of blood."},{"id":"ch18-016","term":"Hesitation","definition":"Inability to start urine stream."},{"id":"ch18-017","term":"Hyposmia","definition":"Reduced ability to smell."},{"id":"ch18-018","term":"Hypoxia","definition":"Oxygen deficiency."},{"id":"ch18-019","term":"Hyperandrogenism","definition":"Condition of high levels of androgen in women."},{"id":"ch18-020","term":"Jaundice","definition":"Yellow discoloration of skin and mucous membranes."},{"id":"ch18-021","term":"Koplik’s spots","definition":"Clustered, white oral lesions."},{"id":"ch18-022","term":"Malaise","definition":"Weakness."},{"id":"ch18-023","term":"Myalgia","definition":"Muscle pain."},{"id":"ch18-024","term":"Opacification","definition":"Process of becoming cloudy or opaque."},{"id":"ch18-025","term":"Otalgia","definition":"Ear pain."},{"id":"ch18-026","term":"Otorrhea","definition":"Ear discharge."},{"id":"ch18-027","term":"Parenteral","definition":"Contact with blood, semen, or another body fluid from an infected patient."},{"id":"ch18-028","term":"Parotitis","definition":"Swollen parotid glands."},{"id":"ch18-029","term":"Peristalsis","definition":"Involuntary contraction and relaxation of the smooth muscle of the intestines."},{"id":"ch18-030","term":"Phonophobia","definition":"Fear of loud sounds."},{"id":"ch18-031","term":"Photophobia","definition":"Sensitivity to light."},{"id":"ch18-032","term":"Polymerize","definition":"Combination of single molecules into polymolecular chains."},{"id":"ch18-033","term":"Polyopia","definition":"Perception of more than one image of a single object."},{"id":"ch18-034","term":"Proton pump inhibitors (PPIs)","definition":"These medications block stomach acid, irreversibly binding to and inhibiting hydrogen-potassium pump."},{"id":"ch18-035","term":"Resonance","definition":"Sound quality that is either deep or full and reverberating."},{"id":"ch18-036","term":"Russel’s sign","definition":"Calluses on the back of hand or knuckles from self-induced vomiting."},{"id":"ch18-037","term":"Sepsis","definition":"Life-threatening organ dysfunction as a host responds to an infection."},{"id":"ch18-038","term":"Splenomegaly","definition":"Enlarged spleen."},{"id":"ch18-039","term":"Syncope","definition":"Temporary loss of consciousness."},{"id":"ch18-040","term":"Tachypnea","definition":"Rapid respirations."},{"id":"ch18-041","term":"Tenesmus","definition":"Straining to defecate or urinate."}]},{"number":19,"title":"Chapter 19","cards":[{"id":"ch19-001","term":"Bullying","definition":"Unwanted aggressive behaviors toward a young person by another youth or group of youths, not including siblings or current dating partner, that involves an observed or perceived power imbalance and is repeated multiple times or is highly likely to be repeated."},{"id":"ch19-002","term":"Cognitive appraisal","definition":"A person’s evaluation of a situation that influences his perception of stress."},{"id":"ch19-003","term":"Confidentiality","definition":"An ethical duty of a psychologist to hold information discussed with a client private and not share this information with anyone unless certain circumstances are met concerning public safety."},{"id":"ch19-004","term":"Depersonalization","definition":"Detachment from one’s thoughts and feelings. Chronic depersonalization refers to depersonalization-derealization disorder and can be found in the DSM-5 under dissociative disorders."},{"id":"ch19-005","term":"Derealization","definition":"A feeling that one’s surroundings are not real."},{"id":"ch19-006","term":"Diaphragmatic breathing","definition":"A style of breathing that uses slowed abdominal breaths to stimulate the vagus nerve and lower the body’s stress response."},{"id":"ch19-007","term":"Emotional intelligence","definition":"A conglomeration of social skills that involve the ability to identify, understand, and manage emotions in order to manage stress, communicate effectively, empathize with others, overcome challenges, and work through conflict."},{"id":"ch19-008","term":"Goal setting","definition":"A method of deciding what you want to accomplish and systematically devising a plan to accomplish the results that you desire based on short-term, step-by-step, realistic, measurable, and recorded standards."},{"id":"ch19-009","term":"Instructional self-talk","definition":"Does not have an influence on motivation; is meant to help improve focus on technical aspects of a movement."},{"id":"ch19-010","term":"Meditation","definition":"A practice consisting of relaxation training (e.g., diaphragmatic breathing and mental imagery) that emphasizes remaining in the present moment with an attitude of acceptance and nonjudgment; helps patients tolerate the pain of their injury during rehabilitation."},{"id":"ch19-011","term":"Mental health services","definition":"Inpatient or outpatient treatment or counseling or use of prescription medication for problems with emotions, nerves, or mental health."},{"id":"ch19-012","term":"Mental imagery","definition":"Cognitive representations of real or imagined actions without actual stimuli from the present environment."},{"id":"ch19-013","term":"Mood disorder","definition":"Also known as an affective disorder; type of psychological disorder characterized by an elevation or lowering of a person’s emotional state that severely affects function (e.g., depression or bipolar)."},{"id":"ch19-014","term":"Negative self-talk","definition":"Typically negatively influences performance, increases anxiety, and destroys confidence."},{"id":"ch19-015","term":"Outcome goals","definition":"Goals focused on the desired end result (e.g., “Finish 1st in the race.”)."},{"id":"ch19-016","term":"Performance goals","definition":"Goals focused on a specific performance standard (e.g., “Run it in 12.2 seconds.”)."},{"id":"ch19-017","term":"Positive self-talk","definition":"A cognitive behavioral strategy used in sport to help an athlete redirect attention toward a task, boost motivation and effort, and improve attitude."},{"id":"ch19-018","term":"Process goals","definition":"Goals focused on “the how,” or the small goals you need to focus on to get to the end result (e.g., “Give maximum effort and have a great attitude today.”)."},{"id":"ch19-019","term":"Progressive muscle relaxation","definition":"An exercise that systematically tenses and relaxes individual muscle groups through directing conscious attention, active contraction, and relaxation."},{"id":"ch19-020","term":"Psychological skills training","definition":"A deliberate, structured training program of psychological strategies and methods that improve physical performance through training aspects involved in the mental aspects of competition."},{"id":"ch19-021","term":"Relaxation techniques","definition":"A variety of methods used to reduce tension, stress, and anxiety in the body."},{"id":"ch19-022","term":"Release of information (ROI)","definition":"A statement signed by a patient that releases confidential information to specified designees."},{"id":"ch19-023","term":"Self-talk","definition":"A person’s internal dialogue that can be used to influence her sense of confidence, self-worth, and perception of the world."},{"id":"ch19-024","term":"State anxiety","definition":"The psychological and physiological transient reactions directly related to adverse situations in a specific moment."},{"id":"ch19-025","term":"Stigma","definition":"When people are shamed because they are different from a social standard."},{"id":"ch19-026","term":"Trait anxiety","definition":"The stable tendency to attend to, experience, and report negative emotions, such as fears, worries, and anxiety, across many situations."}]},{"number":20,"title":"Chapter 20","cards":[{"id":"ch20-001","term":"Achondroplasia","definition":"A hereditary condition signified by short limbs due to ossification of long bone cartilage."},{"id":"ch20-002","term":"Blindisms","definition":"Repetitive movements like hand waving, rocking, or finger flicking. There is no inherent harm in displaying blindisms other than the social stigma."},{"id":"ch20-003","term":"Boosting","definition":"Enacting an autonomic dysreflexia (AD) immediately before competition in an attempt to gain a physiological advantage."},{"id":"ch20-004","term":"Disability","definition":"An umbrella term for impairments, activity limitations, and participation restrictions."},{"id":"ch20-005","term":"Deaf","definition":"People with hearing loss who share the same social structures, cultural views, and history and use American Sign Language (ASL) as their primary mode of communication."},{"id":"ch20-006","term":"Diagnostic overshadowing","definition":"Attributing all symptoms to the primary condition or disability and overlooking other medical issues."},{"id":"ch20-007","term":"Epiphysiolysis","definition":"A medical injury or condition where the epiphysis loosens or separates from the bone shaft."},{"id":"ch20-008","term":"Hard of hearing","definition":"People who have a milder form of hearing loss but can still communicate efficiently with the hearing community."},{"id":"ch20-009","term":"Hearing loss","definition":"A general term that describes people who are hard of hearing or deaf."},{"id":"ch20-010","term":"Hypertonia","definition":"An abnormally high muscle tone or tension."},{"id":"ch20-011","term":"Pathological reflexes","definition":"An abnormal automatic response from the nervous system that may have primitive origins and indicate a loss of cortical inhibition."},{"id":"ch20-012","term":"Person-first terminology","definition":"Statements that identify the person first and then the disability."},{"id":"ch20-013","term":"Poliomyelitis or polio","definition":"A viral infection that affects motor cells of the spinal cord."},{"id":"ch20-014","term":"Shrinkers","definition":"Elastic compression socks that are pulled over a residual amputated limb."},{"id":"ch20-015","term":"Special population","definition":"For the purposes of athletic training, this term includes people in a population subset based on job duties, age, gender identity, and disability."},{"id":"ch20-016","term":"Spina bifida","definition":"A congenital spinal cord injury in which the neural tube does not close completely during the first 4 to 6 weeks of fetal development."},{"id":"ch20-017","term":"Spinal cord injury (SCI)","definition":"An injury that results in complete or partial loss of motor and sensory function below the lesion."},{"id":"ch20-018","term":"Tactical athletes","definition":"People in service professions (e.g., military, firefighters, law enforcement, and emergency responders)."}]},{"number":21,"title":"Chapter 21","cards":[{"id":"ch21-001","term":"Biofeedback","definition":"A modality used to measure muscular contractions through visual and auditory signals to assist patients in strengthening and improving muscular and postural control."},{"id":"ch21-002","term":"Cryotherapy","definition":"The application of cold."},{"id":"ch21-003","term":"Diathermy","definition":"A therapeutic modality used particularly when a heating effect in the tissues is desired without motor or sensory stimulation."},{"id":"ch21-004","term":"Effleurage","definition":"Massage technique of stroking an identified body area."},{"id":"ch21-005","term":"Electromagnetic energy modalities","definition":"A high energy source that is transmitted by the movement of photons."},{"id":"ch21-006","term":"Electrotherapy","definition":"A passive form of treatment where many different forms of electrical stimulation are initiated; used primarily for pain and spasm reduction in addition to increased tissue healing."},{"id":"ch21-007","term":"Massage","definition":"The manipulation of the body’s soft tissues through techniques that bring about specific responses, including stroking, rubbing, kneading, compressing, applying percussion and vibration."},{"id":"ch21-008","term":"Mechanical energy modalities","definition":"Modalities that use an object to provide a force to soft-tissue structures that creates a therapeutic effect."},{"id":"ch21-009","term":"Petrissage","definition":"Massage technique of kneading an identified body area."},{"id":"ch21-010","term":"Soft-tissue mobilization (STM)","definition":"A form of manual therapy intended to address soft-tissue injury that uses instruments and hands-on techniques to enhance healing, reduce pain, and increase range of motion."},{"id":"ch21-011","term":"Tapotement","definition":"Massage technique of percussing an identified body area."},{"id":"ch21-012","term":"Therapeutic modality","definition":"The application of an implement or device that causes physiological changes that improve or facilitate normal function."},{"id":"ch21-013","term":"Thermal energies","definition":"Heat and cold therapies that transfer thermal energy through conduction, convection, radiation, and conversion."},{"id":"ch21-014","term":"Thermotherapy","definition":"The application of heat."},{"id":"ch21-015","term":"Ultrasound","definition":"A deep-heating modality that is inaudible to the human ear."}]},{"number":22,"title":"Chapter 22","cards":[{"id":"ch22-001","term":"Atrophy","definition":"A reduction of muscle mass due to injury or immobility."},{"id":"ch22-002","term":"Closed kinetic chain (CKC) exercises","definition":"Exercises done when an extremity is fixed to an object like the floor or wall."},{"id":"ch22-003","term":"Concentric muscular contraction","definition":"Shortening of a muscle while contracting; critical for power."},{"id":"ch22-004","term":"Eccentric muscular contraction","definition":"Elongation of muscle while contracting to an opposing force (deceleration)."},{"id":"ch22-005","term":"Isokinetic","definition":"Contraction similar to isotonic (concentric and eccentric) but done at constant speed."},{"id":"ch22-006","term":"Isometric","definition":"Strengthening where joint angle and muscular length do not change."},{"id":"ch22-007","term":"Isotonic","definition":"Muscle contraction that occurs with constant tension as the muscle changes length."},{"id":"ch22-008","term":"Open kinetic chain (OKC) exercises","definition":"Exercises where an extremity (e.g., arm or leg) is free to move in space and not fixed to an object."},{"id":"ch22-009","term":"Progressive strengthening (progressive resistance) exercises","definition":"When strengthening concepts are used across the phases of rehabilitation; application is based on tissue healing, patient feedback, and safety."},{"id":"ch22-010","term":"Proprioception","definition":"Also known as kinesthesia; the ability to identify a body’s position in space."},{"id":"ch22-011","term":"Proprioceptive neuromuscular facilitation (PNF)","definition":"A rehabilitation technique primarily used to increase both active and passive range of motion through neuromuscular engagement by relying on reflexive stretching."},{"id":"ch22-012","term":"Therapeutic exercise","definition":"A component of rehabilitation that addresses the return of injured patients to pain-free function or activity."}]},{"number":23,"title":"Chapter 23","cards":[{"id":"ch23-001","term":"Bioavailability","definition":"The amount and rate at which a drug dose reaches the action site unchanged. A medication that reaches the action site unchanged has a bioavailability of 100%."},{"id":"ch23-002","term":"Compounding","definition":"To combine two or more elements (drug components)."},{"id":"ch23-003","term":"Drug","definition":"A chemical that causes a physiological effect when introduced into the body."},{"id":"ch23-004","term":"Drug absorption","definition":"The movement of a drug or medication through the body systems from the point of introduction (site of administration) to the bloodstream."},{"id":"ch23-005","term":"Drug distribution","definition":"The movement of a drug to and from the bloodstream and other tissues in the body."},{"id":"ch23-006","term":"Formulary","definition":"An entity that maintains a list of drugs that are available as part of a service or insurance provision."},{"id":"ch23-007","term":"Half-life","definition":"The rate at which a drug is metabolized or excreted is called the half-life."},{"id":"ch23-008","term":"Over the counter (OTC)","definition":"A drug that is sold retail without a prescription."},{"id":"ch23-009","term":"Pharmacodynamics","definition":"The study of how a drug affects the body, which includes time, intensity, and adverse effects."},{"id":"ch23-010","term":"Pharmacokinetics","definition":"How the body processes a drug, which includes metabolism, absorption, distribution, and elimination."},{"id":"ch23-011","term":"Pharmacology","definition":"The science of drug action, effect, and uses."},{"id":"ch23-012","term":"Pharmacy","definition":"An entity that sells, dispenses, and prepares medications."}]},{"number":24,"title":"Chapter 24","cards":[{"id":"ch24-001","term":"Boxer fracture","definition":"Fracture of the fifth metacarpal neck having apex dorsal angulation."},{"id":"ch24-002","term":"Cast index","definition":"The ratio of sagittal to coronal width from the inside edges of the cast at the fracture site."},{"id":"ch24-003","term":"Compartment syndrome","definition":"Neurovascular compromise in soft tissue resulting from increased pressure in a rigid fascial compartment that prevents adequate muscle perfusion."},{"id":"ch24-004","term":"Displaced fracture","definition":"Translation, angulation, rotation, or shortening occurring between two opposing segments of a fractured bone."},{"id":"ch24-005","term":"Fracture reduction","definition":"Correction of a displaced fracture using slight exaggeration of the deformity, traction, and then reversal of the deformity to reestablish anatomical alignment."},{"id":"ch24-006","term":"Intrinsic plus position","definition":"MCP joints flexed to as close to 70 to 90 degrees as is comfortably achievable with the PIP and DIP joints extended."},{"id":"ch24-007","term":"Position of function","definition":"Placing the body so that the ankle is in neutral dorsiflexion (no equinus), there is 30 degrees of wrist extension, and the thumb is opposed to midway between maximal radial and palmar abduction."}]}];
